import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    S = input_data[0]
    K = int(input_data[1])

    n = len(S)
    if K > 26:
        print(-1)
        return

    left = 0
    max_len = -1
    char_count = {}
    unique_count = 0

    for right in range(n):
        char = S[right]
        if char not in char_count:
            char_count[char] = 0
        char_count[char] += 1

        if char_count[char] == 1:
            unique_count += 1

        while unique_count > K:
            left_char = S[left]
            char_count[left_char] -= 1
            if char_count[left_char] == 0:
                del char_count[left_char]
                unique_count -= 1
            left += 1

        if unique_count == K:
            current_len = right - left + 1
            if current_len > max_len:
                max_len = current_len

    print(max_len)

if __name__ == "__main__":
    solve()
